#include <bits/stdc++.h>
using namespace std;
int main(int c, char** v) { ifstream in(v[1]), out(v[2]), ans(v[3]); int n, m; in >> n >> m; vector<array<long long,3>> e(m); for (auto& [a, b, w] : e) in >> a >> b >> w; int u; in >> u; vector<long long> d(n + 1, LLONG_MAX / 4); d[u] = 0; for (int it = 0; it < n; it++) for (auto [a, b, w] : e) { d[b] = min(d[b], d[a] + w); d[a] = min(d[a], d[b] + w); } long long want, got; ans >> want; if (!(out >> got) || got != want) return 1; vector<bool> used(m, false); long long s = 0; vector<long long> t(n + 1, LLONG_MAX / 4); t[u] = 0; vector<int> ids; for (int i = 0; i < n - 1; i++) { int id; if (!(out >> id) || id < 1 || id > m || used[id - 1]) return 1; used[id - 1] = true; s += e[id - 1][2]; ids.push_back(id - 1); } for (int it = 0; it < n; it++) for (int id : ids) { auto [a, b, w] = e[id]; t[b] = min(t[b], t[a] + w); t[a] = min(t[a], t[b] + w); } if (s != want || t != d) return 1; return 0; }
